ga_S(){return"\ubc1b\ub294 \ubaa8\ub4e0 \ud53c\ud574\uac00 \uadf8 \uac12\ub9cc\ud07c \uc904\uc5b4\uc694. \ubaa8\ub4e0 \ubcf4\ud638\ub9c9\uc740 \ubc84\ud2f0\ub294 \ub3d9\uc548 \uc790\uccb4 \ud53c\ud574 \uac10\uc18c\ub97c \uc8fc\uc9c0\ub9cc, \uc9c0\uc18d \uc2dc\uac04\uc774 \uc788\ub294 \ubcc4\ub3c4 \ud6a8\uacfc\ub85c\ub3c4 \uac78\ub9b4 \uc218 \uc788\uc5b4\uc694. \ubaa8\ub4e0 \uac10\uc18c\ub97c \ud569\uccd0 \ucd5c\ub300 50%\uc608\uc694."},
ga0j(){return"\ub3cc\uc774 \ub41c Ovaling\uc740 \ud134\uc744 \uac74\ub108\ub6f0\uace0 \ubc1b\ub294 \ud53c\ud574\uac00 \uc808\ubc18\uc774 \ub3fc\uc694. \ud68c\ubcf5\uc774\ub098 \uc815\ud654\ub97c \ubc1b\uc73c\uba74 \ubc14\ub85c \ud480\ub824\ub098\uace0, \uc544\ub2c8\uba74 \ucd5c\ub300 3\ud134 \ub4a4\uc5d0 \ub2e4\uc2dc \ud480\ub824\ub098\uc694. Ovaling\uc744 \ub3cc\ub85c \ub9cc\ub4dc\ub294 \uac74 \uba54\ub450\uc0ac\ubfd0\uc774\uc5d0\uc694."},
