Mq(a,b,c){return""+a+"% \ud655\ub960\ub85c "+b+" [[\ubc29\ud574]]\ud574\uc694: \ucfe8\ud0c0\uc784\uc774 \uc788\ub294 \uc2a4\ud0ac\uc774 \uc900\ube44\ub418\uae30\uae4c\uc9c0 "+c+" \ub354 \uac78\ub824\uc694."},
Mr(a,b,c){return a+" "+b+" \ub3d9\uc548 [[\uc0dd\uba85\uc758 \ubd88\uc528]]\ub97c \uc918\uc694: \uc4f0\ub7ec\uc838\ub3c4 \ubc14\ub85c \ucd5c\ub300 <hp>\uccb4\ub825</hp>\uc758 "+c+"%\ub85c \uc77c\uc5b4\ub098\uc694 (\uc804\ud22c\ub9c8\ub2e4 \ud55c \ubc88)."},
M3(a){return"\uce58\uba85\ud0c0\uac00 \ub098\uc62c \ub54c\ub9c8\ub2e4 \ud55c \ubc88 \ub354 \uacf5\uaca9\ud574\uc694 (\ucd5c\ub300 "+a+"\ud68c \ucd94\uac00)."},
zb(a){return"\uce58\uba85\ud0c0 \uc5f0\uc1c4 +"+a},
Vp(a){return"\uc774 Ovaling\uc758 <fx:heal>\ud68c\ubcf5</fx>\uacfc <fx:shield>\ubcf4\ud638\ub9c9</fx>\uc774 "+a+"% \uac15\ud574\uc838\uc694."},
